package cli

import (
	"bytes"
	"fmt"
	"io"
	"sort"
	"strings"

	"github.com/spf13/cobra"
)

// DocsPath is where the generated command reference lives, relative to
// the repository root. `make docs-cli` writes it; a test fails when it is
// stale.
const DocsPath = "docs/cli.md"

// cliDocsHeader opens the generated reference. It never mentions versions,
// dates, or paths so the file only changes when the command tree does.
const cliDocsHeader = `# sc command reference

<!-- Generated by ` + "`make docs-cli`" + ` from the cobra command tree. Do not edit by hand:
     change the command's Long/Short/Example/flags in internal/cli and regenerate. -->

Every command, flag, and example of the ` + "`sc`" + ` binary, in the words of
` + "`sc <command> --help`" + `. Configuration keys are documented in
[config.md](config.md).

`

// WriteDocs renders the whole command tree of root as one Markdown file:
// an index, then one section per visible command (depth first, siblings in
// name order) with its synopsis, usage, examples, flags, and related
// commands. The output is deterministic so it can be diffed and committed.
func WriteDocs(w io.Writer, root *cobra.Command) error {
	root.InitDefaultHelpCmd()
	cmds := docsCommands(root)

	var b bytes.Buffer
	b.WriteString(cliDocsHeader)
	b.WriteString("## Commands\n\n")
	for _, c := range cmds {
		fmt.Fprintf(&b, "- [%s](#%s) — %s\n", c.CommandPath(), docsAnchor(c), c.Short)
	}
	b.WriteString("\n")
	for _, c := range cmds {
		docsCommand(&b, c)
	}
	_, err := w.Write(b.Bytes())
	return err
}

// Docs returns the Markdown WriteDocs would write for a fresh command
// tree, as a string.
func Docs() (string, error) {
	var b bytes.Buffer
	if err := WriteDocs(&b, NewRootCommand(io.Discard)); err != nil {
		return "", err
	}
	return b.String(), nil
}

// docsCommands flattens the visible command tree depth first, siblings in
// name order, starting with root itself.
func docsCommands(root *cobra.Command) []*cobra.Command {
	var out []*cobra.Command
	var walk func(c *cobra.Command)
	walk = func(c *cobra.Command) {
		out = append(out, c)
		subs := make([]*cobra.Command, 0, len(c.Commands()))
		for _, s := range c.Commands() {
			if s.IsAvailableCommand() && !s.IsAdditionalHelpTopicCommand() {
				subs = append(subs, s)
			}
		}
		sort.Slice(subs, func(i, j int) bool { return subs[i].Name() < subs[j].Name() })
		for _, s := range subs {
			walk(s)
		}
	}
	walk(root)
	return out
}

// docsCommand renders one command section.
func docsCommand(b *bytes.Buffer, c *cobra.Command) {
	c.InitDefaultHelpFlag()

	fmt.Fprintf(b, "## %s\n\n", c.CommandPath())
	if c.Short != "" {
		fmt.Fprintf(b, "%s\n\n", c.Short)
	}
	if c.Long != "" {
		fmt.Fprintf(b, "### Synopsis\n\n%s\n\n", strings.TrimRight(c.Long, "\n"))
	}
	if usage := docsUsage(c); usage != "" {
		b.WriteString("### Usage\n\n")
		docsCode(b, usage)
	}
	if c.Example != "" {
		b.WriteString("### Examples\n\n")
		docsCode(b, docsDedent(c.Example))
	}
	if flags := c.NonInheritedFlags(); flags.HasAvailableFlags() {
		b.WriteString("### Options\n\n")
		docsCode(b, strings.TrimRight(flags.FlagUsages(), "\n"))
	}
	if flags := c.InheritedFlags(); flags.HasAvailableFlags() {
		b.WriteString("### Options inherited from parent commands\n\n")
		docsCode(b, strings.TrimRight(flags.FlagUsages(), "\n"))
	}
	if related := docsRelated(c); len(related) > 0 {
		b.WriteString("### See also\n\n")
		for _, r := range related {
			fmt.Fprintf(b, "- [%s](#%s) — %s\n", r.CommandPath(), docsAnchor(r), r.Short)
		}
		b.WriteString("\n")
	}
}

// docsUsage mirrors the Usage block of cobra's help: the use line when the
// command runs, plus "<path> [command]" when it has subcommands.
func docsUsage(c *cobra.Command) string {
	var lines []string
	if c.Runnable() {
		lines = append(lines, c.UseLine())
	}
	if c.HasAvailableSubCommands() {
		lines = append(lines, c.CommandPath()+" [command]")
	}
	return strings.Join(lines, "\n")
}

// docsRelated lists the parent (first) and the visible children (name
// order) of c.
func docsRelated(c *cobra.Command) []*cobra.Command {
	var out []*cobra.Command
	if c.HasParent() {
		out = append(out, c.Parent())
	}
	subs := make([]*cobra.Command, 0, len(c.Commands()))
	for _, s := range c.Commands() {
		if s.IsAvailableCommand() && !s.IsAdditionalHelpTopicCommand() {
			subs = append(subs, s)
		}
	}
	sort.Slice(subs, func(i, j int) bool { return subs[i].Name() < subs[j].Name() })
	return append(out, subs...)
}

// docsDedent strips the trailing newlines and the indentation the help
// template needs (see indent) from an Example block.
func docsDedent(s string) string {
	lines := strings.Split(strings.TrimRight(s, "\n"), "\n")
	common := -1
	for _, l := range lines {
		if strings.TrimSpace(l) == "" {
			continue
		}
		n := len(l) - len(strings.TrimLeft(l, " \t"))
		if common < 0 || n < common {
			common = n
		}
	}
	if common <= 0 {
		return strings.Join(lines, "\n")
	}
	for i, l := range lines {
		if len(l) >= common {
			lines[i] = l[common:]
		}
	}
	return strings.Join(lines, "\n")
}

// docsCode writes s as a fenced code block followed by a blank line.
func docsCode(b *bytes.Buffer, s string) {
	fmt.Fprintf(b, "```\n%s\n```\n\n", s)
}

// docsAnchor is the GitHub-style heading anchor of a command section
// ("sc config show" -> "sc-config-show").
func docsAnchor(c *cobra.Command) string {
	return strings.ReplaceAll(c.CommandPath(), " ", "-")
}
